def clean(s):return ' '.join(unescape(re.sub('<[^>]+>',' ',s)).split())
sources={}
page_map={
'09':{'01':2,'02':3,'03':4,'04':4},
'10':{'01':2,'02':2,'03':4,'04':4}}
for l in ['09','10']:
    html=(blind/f'lesson-{l}.html').read_text()
    for m in re.finditer(r'<p\b([^>]*)>(.*?)</p>',html,re.S):
        im=re.search(r'data-canvas-edit-key="(ch14-l\d+-teaching-(\d+)-p(\d+))"',m.group(1))
        if im:
            sid,sec,para=im.groups();page=page_map[l][sec]
            if l=='09' and sec=='02' and para=='4':page=4
            if l=='09' and sec=='04' and para=='4':page=5
            if l=='10' and sec=='02' and int(para)>=3:page=3
            pp=[2,3] if l=='10' and sec=='02' and para=='2' else [page]
            sources[sid]={'file':f'lesson-{l}.html','locator':f'#{sid}','rendered_pages':pp,'visible_text':clean(m.group(2))}
extra={
'L09-W2':('09',5,'#ch14-l09-worked ol li:nth-child(2)','Trace A upstream: weaker inhibition permits FSH/LH stimulation to rise. Trace back to the target: poor follicular responsiveness means more stimulation need not restore maturation or ovulation.'),
'L09-W3':('09',5,'#ch14-l09-worked ol li:nth-child(3)','Locate the change in Model B: an external inhibitory signal is supplied. Trace upstream output: normal FSH/LH stimulation and the LH surge can be suppressed. Responsive ovaries still need the appropriate stimulation to complete the normal sequence.'),
'L10-W2':('10',5,'#ch14-l10-worked ol li:nth-child(2)','Locate the process that can continue: ovulation releases a secondary oocyte at an ovary. Blocking the oviduct does not itself remove that ovarian event.'),
'L10-W4':('10',5,'#ch14-l10-worked ol li:nth-child(4)','Answer the question: no. Removing the pathogen is different from removing established scar tissue. We need separate evidence about the ducts before claiming that the normal route is restored.'),
'L09-FIG':('09',3,'.science-figure img (actual rendered pixels)','Three ovarian boxes read Early follicular phase / Follicles develop, Late follicular phase / Estrogen rises, and After ovulation / Corpus luteum active. The corresponding uterine boxes read Menstrual flow / Part of lining is shed, Rebuilding / Endometrium grows, and Maintenance / Progesterone supports lining. Downward arrows connect each pair. The footer states Flow overlaps early follicular development and Hormone decline after corpus-luteum regression permits the next flow.'),
'L10-FIG':('10',3,'.science-figure img (actual rendered pixels)','Normal sagittal female reproductive anatomy includes clearly legible labels for oviduct, ovary, uterus, cervix and vagina; the image does not show infection, scars, both oviducts as a bilateral frontal pair, or a gamete transport sequence.')}
for sid,(l,p,loc,txt) in extra.items():sources[sid]={'file':f'lesson-{l}.html','locator':loc,'rendered_pages':[p],'visible_text':txt}

records=[]
def task(id,lesson,category,prompt,answer,refs,note,demand,page=None):
    records.append({'id':id,'lesson':lesson,'category':category,'prompt':prompt,'first_attempt_answer':answer,'support_ids':refs,'support_map':note,'cognitive_demand':demand,'prompt_rendered_pages':page,'visible_support_judgment':'Sufficient for this answer within the stated prerequisite; no unseen content used','feedback_status':'Not accessed before freeze','correctness_status':'Ungraded first attempt'})
S=lambda l,sec,p:f'ch14-l{l:02d}-teaching-{sec:02d}-p{p}'
task('ch14-l09-check-mc-1',9,'required_selection','In a functioning control system, reduced ovarian hormone feedback can produce which response?','Increased FSH and LH stimulation',[S(9,2,2)],'The paragraph identifies reduced inhibitory ovarian feedback and explicitly says a functioning anterior pituitary can release more FSH and LH.','Direct recognition of taught relation',[6])
task('ch14-l09-check-mc-2',9,'required_selection','Which statement correctly explains one effect of combined hormonal contraception?','Feedback can reduce the normal LH surge and prevent ovulation',[S(9,4,1)],'The supplied estrogen/progestin signals reduce pituitary stimulation; the paragraph explicitly links LH-surge suppression to prevention of ovulation.','Direct recognition of taught relation',[7])
task('ch14-l09-check-writing-1',9,'required_writing','Explain why low ovarian hormone output and high pituitary hormone output can occur together.','Ovarian hormones normally inhibit the hypothalamus and anterior pituitary. If ovarian output falls, less inhibition reaches a functioning control system, so the anterior pituitary can release more FSH and LH. Reduced inhibin also contributes, especially to higher FSH. The extra stimulation does not guarantee more ovarian output when follicles respond poorly.',[S(9,2,2),S(9,2,3),'L09-W2'],'02-p2 supplies the inhibition → reduced inhibition → higher FSH/LH chain and inhibin qualification; 02-p3 and worked step 2 explain why the weak target response can persist.','Reconstruct a taught causal chain',[7])
task('ch14-l09-check-writing-2',9,'required_writing','Contrast a cycle without pregnancy with early pregnancy in terms of corpus-luteum activity and endometrial support.','Without pregnancy support, the corpus luteum regresses, its progesterone and estrogen output falls, and the functional endometrial lining is shed. In early pregnancy, developing trophoblast releases hCG, which supports the corpus luteum. The corpus luteum keeps supplying progesterone and estrogen, maintaining support for the endometrium rather than following its usual decline.',[S(9,1,2),S(9,1,3),S(9,3,1),S(9,3,2),S(9,3,3)],'01-p2/3 supply the unsupported baseline and shedding; 03-p1/2/3 supply the trophoblast → hCG → corpus luteum → hormones → lining chain.','Compare two explicitly taught causal pathways',[7])
task('ch14-l09-guided-q1',9,'supported','Which signal helps maintain the corpus luteum in early pregnancy?','hCG',[S(9,3,2)],'The paragraph explicitly states that hCG travels in blood and supports the corpus luteum.','Retrieval',[6])
task('ch14-l09-guided-q2',9,'supported','Why does a combined contraceptive pill not protect against an STI?','Changing hormonal feedback does not create a barrier to pathogen transmission',[S(9,4,3)],'The paragraph directly distinguishes altered hormone feedback from a physical barrier to infectious organisms.','Direct recognition',[6])
task('lesson-09-stop',9,'stop','Would low progesterone in one sample prove that ovulation never occurred?','No. One sample only shows that progesterone was low when it was taken. It may have been taken before the usual post-ovulation rise, so the timing and a more complete pattern are needed before interpreting ovulation.',[S(9,1,4)],'01-p4 gives this precise limitation and the pre-rise sampling example.','Apply a stated evidence limitation',[6])
task('lesson-09-new-optional',9,'new_optional','Optional model challenge: hCG is present in early pregnancy, but in a constructed model the corpus luteum cannot respond to it. No other tissue supplies enough progesterone or estrogen to replace that lost output. Would the presence of hCG alone guarantee maintenance of the endometrium? Trace the missing link.','No. hCG is the signal that normally supports the corpus luteum, but the target cannot respond in this model. Therefore the normal link from hCG to continued corpus-luteum progesterone and estrogen output is broken. With no adequate replacement source, the presence of hCG alone cannot guarantee hormonal support of the endometrium.',[S(9,3,2),S(9,3,3),'L09-W2'],'03-p2/3 supply the source–signal–target–output chain; the challenge itself supplies target failure and absence of replacement. Worked step 2 shows that a signal need not restore an unresponsive target.','Near transfer: interrupt an explicitly taught pathway',[5])
task('ch14-source-OBJ_2131183',9,'original_saved_optional','Explain how the hormones in a combined contraceptive pill can reduce the chance of pregnancy. Trace the feedback effect to ovarian activity.','A combined pill supplies an estrogen and a progestin, which has progesterone-like activity. Their feedback on the hypothalamus and anterior pituitary reduces the normal FSH/LH stimulation of the ovaries. Reduced follicular development and suppression of the LH surge make ovulation less likely, so an oocyte is less likely to be available for fertilization.',[S(9,4,1),S(9,4,2)],'04-p1 defines the supplied signals and traces their effect through FSH/LH to follicular development and ovulation. This is a written answer to the saved-response prompt, not a test of saving or persistence.','Reconstruct a taught mechanism',[7])
task('ch14-l10-check-mc-1',10,'required_selection','Which chain best explains one way an STI can reduce fertility?','Infection → inflammation and scarring → disrupted transport',[S(10,2,2),S(10,2,3)],'02-p2 traces infection/PID through inflammation and scar blockage to disrupted meeting or embryo movement; 02-p3 connects this to infertility.','Direct recognition of taught causal chain',[6])
task('ch14-l10-check-mc-2',10,'required_selection','Which comparison is accurate?','Hormonal contraception and STI risk reduction are different functions',[S(10,4,1),S(10,4,2)],'04-p1 states hormonal suppression changes oocyte availability without preventing pathogen exposure; 04-p2 supplies the separate barrier mechanism.','Direct recognition',[6])
task('ch14-l10-check-writing-1',10,'required_writing','Explain how an STI could interfere with reproduction while gamete and hormone production continue.','An infection can cause inflammation and leave scar tissue that narrows or blocks an oviduct. The ovaries may still develop follicles, release an oocyte and produce hormones, but the damaged route can prevent sperm and the oocyte from meeting or interfere with early-embryo movement toward the uterus. Gamete production, hormone production and an open transport pathway are different functions, so damage to one does not require all the others to stop.',[S(10,1,1),S(10,2,1),S(10,2,2),S(10,2,3),'L10-W2'],'01-p1 separates functions; 02-p1 locates ovulation at the ovary; 02-p2/3 explain duct damage and consequences; worked step 2 explicitly preserves ovulation with blocked ducts.','Reconstruct a taught mechanism and distinguish functions',[6])
task('ch14-l10-check-writing-2',10,'required_writing','A student says, “If a method prevents pregnancy, it must prevent STIs too.” Explain the flaw using two different mechanisms.','Preventing pregnancy and reducing infection transmission act on different parts of the process. Combined hormonal contraception can suppress the LH surge and ovulation, reducing the availability of an oocyte, but it does not block exposure to pathogens. An appropriate condom used correctly and consistently is a physical barrier that reduces contact with infectious material and can obstruct sperm passage. It can reduce STI risk, although exposed skin outside its coverage means protection is not absolute.',[S(10,4,1),S(10,4,2)],'04-p1 supplies the hormone-control mechanism and its STI limit; 04-p2 supplies the physical-barrier mechanism and its coverage limitation.','Compare two explicitly taught mechanisms',[7])
task('ch14-l10-guided-q1',10,'supported','Why might the absence of symptoms fail to rule out an STI?','Some infections are asymptomatic',[S(10,1,3)],'The paragraph defines asymptomatic as no obvious symptoms and rejects appearance or lack of discomfort as proof of no infection.','Direct recognition',[5])
task('ch14-l10-guided-q2',10,'supported','Which consequence most directly follows scarring that blocks an oviduct?','Disrupted reproductive-cell transport',[S(10,2,2)],'The paragraph links scar narrowing/blockage to failure of gametes to meet or abnormal embryo movement.','Direct recognition',[5])
task('lesson-10-stop',10,'stop','Would treating an infection necessarily remove all scarring it caused?','No. Removing the pathogen does not necessarily undo established scar tissue. Separate evidence would be needed to know whether the damaged transport route had reopened.',[S(10,3,4),'L10-W4'],'03-p4 explicitly distinguishes treatment of infection from reversing tissue damage; worked step 4 applies this to the ducts.','Apply a stated distinction',[6])
task('lesson-10-new-optional',10,'new_optional','Optional comparison: Model A has open oviducts but no ovulation because the LH surge is suppressed. Model B has normal ovulation but scar tissue blocking both oviducts. Identify the disrupted step in each model. Would removing the infection that caused the old scar tissue necessarily repair either stated problem? Explain.','In Model A the disruption is the hormonal stimulation needed for ovulation, so an oocyte is not released despite open ducts. In Model B ovulation continues, but the blocked oviducts disrupt the normal route for sperm and the oocyte to meet. Removing the infection does not necessarily restore the suppressed LH surge in A and does not by itself show that old scarring has disappeared in B. Neither stated problem is necessarily repaired just by removing the infection.',[S(10,4,1),S(10,2,1),S(10,2,2),S(10,3,4),'L10-W4'],'04-p1 supplies LH-suppression/ovulation; 02-p1/2 separate ovulation from transport; 03-p4 and worked step 4 reject equating pathogen removal with structural repair. The prompt supplies the two model states and gives no basis to infer restoration of the LH surge.','Near transfer: compare control failure with transport failure',[5])

concepts={
'menopause':(9,'Menopause is the end of menstrual cycling associated with declining ovarian follicular activity.','Menopause','Reduced ovarian hormone output can remove some inhibitory feedback, allowing a functioning anterior pituitary to increase FSH and LH rather than making them both low.',[S(9,2,1)],[S(9,2,2),S(9,2,3)]),
'hcg':(9,'hCG is human chorionic gonadotropin, released by developing trophoblast tissue in early pregnancy. It supports the corpus luteum so that its hormone output continues.','hCG','hCG and progesterone are different hormones. Trophoblast releases hCG, which supports the corpus luteum; the corpus luteum releases progesterone, which helps maintain the endometrium.',[S(9,3,1),S(9,3,2)],[S(9,3,3)]),
'hormonal-contraception':(9,'Hormonal contraception uses hormones or hormone-like substances to alter reproductive processes for conception control. In the combined-method example, estrogen and a progestin reduce FSH/LH stimulation and suppress the LH surge to help prevent ovulation.','Hormonal contraception','Preventing pregnancy by altering hormone feedback does not create a barrier to pathogens. A combined contraceptive pill does not protect against STIs.',[S(9,4,1)],[S(9,4,3)]),
'sti':(10,'An STI is a sexually transmitted infection, an infection that can pass through sexual contact.','STI','A person can have an STI without obvious symptoms because some infections are asymptomatic. Absence of symptoms alone cannot rule out infection.',[S(10,1,2)],[S(10,1,3)]),
'pathogen':(10,'A pathogen is an organism or infectious agent capable of causing disease.','Pathogen','A pathogen is an organism or infectious agent capable of causing disease. A reproductive hormone is a chemical message acting on responsive cells, not a pathogen.',[S(10,1,2)],[S(10,1,2)]),
'pelvic-inflammatory-disease':(10,'Pelvic inflammatory disease, or PID, involves inflammation in upper female reproductive structures, often associated with infection. Untreated chlamydia or gonorrhea can spread there and contribute to it.','Pelvic inflammatory disease','Normal ovarian hormones do not protect a duct from infection-related tissue damage. Inflammation and healing can leave scar tissue that narrows or blocks an oviduct even while ovarian function continues.',[S(10,2,2)],[S(10,2,2),'L10-W2']),
'infertility':(10,'Infertility is difficulty establishing a pregnancy due to one or more reproductive factors. For example, damage to a transport pathway can make pregnancy harder to establish.','Infertility','Infertility does not require every gonad to stop making hormones and gametes. Ovarian activity can continue while a scarred oviduct disrupts the route needed for sperm and the oocyte to meet.',[S(10,2,3)],[S(10,1,1),S(10,2,2),'L10-W2']),
'ectopic-pregnancy':(10,'An ectopic pregnancy is a pregnancy in which implantation occurs outside the normal uterine site.','Ectopic pregnancy','Normal fertilization in an oviduct is not an ectopic pregnancy. The defining difference is implantation outside the normal uterine site, not the normal location of fertilization.',[S(10,2,3)],[S(10,2,3)])}
# The infertility definition's full wording is in visible vocabulary, not wholly in 02-p3.
sources['L10-V-INF']={'file':'lesson-10.html','locator':'#lesson-10-anchor-words; infertility dt/dd','rendered_pages':[2],'visible_text':'Difficulty establishing a pregnancy due to one or more reproductive factors.'}
cs=list(concepts['infertility']);cs[4]=['L10-V-INF',S(10,2,3)];concepts['infertility']=tuple(cs)
